// Some portions generated by Claude
package org.eclipse.rdf4j.sail.helpers;

import static org.assertj.core.api.Assertions.assertThat;
import static org.mockito.Mockito.CALLS_REAL_METHODS;
import static org.mockito.Mockito.doReturn;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.withSettings;

import java.util.Collections;

import org.eclipse.rdf4j.common.iteration.CloseableIteration;
import org.eclipse.rdf4j.common.iteration.CloseableIteratorIteration;
import org.eclipse.rdf4j.common.iteration.RowPassThroughIteration;
import org.eclipse.rdf4j.query.BindingSet;
import org.eclipse.rdf4j.query.algebra.SingletonSet;
import org.eclipse.rdf4j.query.impl.EmptyBindingSet;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.parallel.Isolated;
import org.junit.jupiter.api.parallel.ResourceLock;
import org.junit.jupiter.api.parallel.Resources;

@ResourceLock(Resources.SYSTEM_PROPERTIES)
@Isolated("Toggles the debug system property")
class PassThroughHelperIterationTest {

	private static final String DEBUG_PROPERTY = "org.eclipse.rdf4j.repository.debug";
	private String previousDebug;

	@BeforeEach
	void rememberDebug() {
		previousDebug = System.getProperty(DEBUG_PROPERTY);
	}

	@AfterEach
	void restoreDebug() {
		if (previousDebug == null) {
			System.clearProperty(DEBUG_PROPERTY);
		} else {
			System.setProperty(DEBUG_PROPERTY, previousDebug);
		}
	}

	@Test
	void cleanerPathRegistrationChainReachesTheOriginalIteration() {
		System.setProperty(DEBUG_PROPERTY, "false");
		assertChainReaches(2);
	}

	@Test
	void debugPathRegistrationChainReachesTheOriginalIteration() {
		System.setProperty(DEBUG_PROPERTY, "true");
		assertChainReaches(1);
	}

	@Test
	void tupleExprWrapperReturnsItsDelegateAsPassThroughSource() {
		CloseableIteration<BindingSet> delegate = new CloseableIteratorIteration<>(
				Collections.<BindingSet>singletonList(EmptyBindingSet.getInstance()).iterator());
		var wrapper = new TupleExprWrapperIteration<BindingSet, RuntimeException>(delegate, new SingletonSet());
		assertThat((Object) wrapper).isInstanceOf(RowPassThroughIteration.class);
		assertThat(((RowPassThroughIteration) wrapper).passThroughSource()).isSameAs(delegate);
		BindingSet row = wrapper.next();
		assertThat(row).isSameAs(EmptyBindingSet.getInstance());
		wrapper.close();
	}

	private static void assertChainReaches(int expectedHops) {
		AbstractSail sail = mock(AbstractSail.class, withSettings().useConstructor().defaultAnswer(CALLS_REAL_METHODS));
		doReturn(false).when(sail).tracksResultPulls();
		AbstractSailConnection connection = mock(AbstractSailConnection.class,
				withSettings().useConstructor(sail).defaultAnswer(CALLS_REAL_METHODS));
		CloseableIteration<Integer> original = new CloseableIteratorIteration<>(
				Collections.singletonList(1).iterator());
		CloseableIteration<Integer> registered = connection.registerIteration(original);
		try {
			CloseableIteration<?> current = registered;
			int hops = 0;
			while (current != original) {
				assertThat((Object) current).isInstanceOf(RowPassThroughIteration.class);
				current = ((RowPassThroughIteration) current).passThroughSource();
				hops++;
				assertThat(hops).isLessThanOrEqualTo(expectedHops);
			}
			assertThat(hops).isEqualTo(expectedHops);
		} finally {
			registered.close();
			connection.close();
		}
	}
}
